    $stmt->bindParam(':xui_api_token', $xuiApiToken);
    $stmt->bindParam(':remna_api_token', $remnaApiToken);
    if ($finalType == "pasarguard") {
        $stmt->bindParam(':pasarguard_auth_mode', $pasarguardAuthMode);
    }
