        $stmt->bindParam(':rebecca_service_id', $rebeccaServiceIdSwitch);
    }
    $stmt->bindParam(':code_panel', $codePanel);
    $stmt->execute();
    update("user", "Processing_value", $namePanel, "id", $from_id);
